import { Redis } from 'ioredis';

type Result<T, E = Error> = 
  | { ok: true; value: T }
  | { ok: false; error: E };

interface RateLimitError {
  type: 'RATE_LIMIT_EXCEEDED' | 'REDIS_ERROR' | 'UNKNOWN_ERROR';
  message: string;
}

export class RateLimiter {
  constructor(
    private redis: Redis,
    private maxRequests: number,
    private windowSeconds: number
  ) {}

  async checkRateLimit(key: string): Promise<Result<boolean, RateLimitError>> {
    const currentTime = Date.now() / 1000;
    const windowStart = currentTime - this.windowSeconds;

    try {
      // Remove old entries
      await this.redis.zremrangebyscore(key, 0, windowStart);

      // Count requests in current window  
      const requestCount = await this.redis.zcard(key);

      if (requestCount >= this.maxRequests) {
        return {
          ok: false,
          error: {
            type: 'RATE_LIMIT_EXCEEDED',
            message: `Rate limit exceeded for ${key}`
          }
        };
      }

      // Add current request
      await this.redis.zadd(key, currentTime, currentTime.toString());
      await this.redis.expire(key, this.windowSeconds);

      return { ok: true, value: true };

    } catch (error) {
      if (error instanceof Error && error.message.includes('Redis')) {
        return {
          ok: false,
          error: {
            type: 'REDIS_ERROR',
            message: `Redis connection failed: ${error.message}`
          }
        };
      }

      return {
        ok: false,
        error: {
          type: 'UNKNOWN_ERROR',
          message: `Unexpected error: ${error}`
        }
      };
    }
  }
}

